// Разметка вакансий: навыки, грейд, категория, удалённость.
//
// Размечаем только то, чего ещё нет в листе Analyzed Jobs: иначе каждый
// запуск дописывал бы весь лист заново и данные множились.
const already = new Set(
  $('Get row(s) in sheet1').all()
    .map(i => String(i.json.job_id ?? '').trim())
    .filter(Boolean)
);

// Значения из таблицы приводим к строке явно: Google Sheets отдаёт числа
// числами, и заголовок вида "2025" ронял .toLowerCase().
// Ищем в заголовке, тегах и описании: грейд в заголовке указывают редко.
// Поиск по целым словам — иначе "ai" находится в email, available, training.
const keywords = {
  'sql': ['sql'],
  'python': ['python'],
  'api': ['api', 'apis', 'rest api'],
  'javascript': ['javascript', 'js'],
  'react': ['react', 'react.js', 'reactjs'],
  'node': ['node', 'node.js', 'nodejs'],
  'aws': ['aws', 'amazon web services'],
  'docker': ['docker'],
  'kubernetes': ['kubernetes', 'k8s'],
  'ai': ['ai', 'artificial intelligence'],
  'machine learning': ['machine learning', 'ml'],
  'project manager': ['project manager', 'project management'],
};

function hasWord(str, word) {
  const safe = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^a-z0-9+#])' + safe + '($|[^a-z0-9+#])', 'i').test(str);
}

// Категория вакансии определяется по должности.
//
// Раньше значением по умолчанию было 'Engineering', и всё нераспознанное
// становилось инженерной вакансией: 362 записи из 549, включая «Cleaner»
// и «Traffic Controller». Теперь по умолчанию 'Other' — источник RemoteOK
// это доска общего профиля, и большая часть его вакансий к ИТ не относится.
//
// Теги в разборе не участвуют: у RemoteOK они слишком широкие — у вакансии
// «HR Generalist» стоит тег «support», и по тегам она становится инженером
// поддержки.
//
// Множественное число обязательно во всех шаблонах: \bengineer\b не совпадает
// со словом «Engineers», и без «s?» теряется половина технических вакансий.
const CATEGORY_RULES = [
  ['AI', /\b(ai|artificial intelligence|machine learning|ml|deep learning|llm|nlp|computer vision|data scientists?|ml engineers?)\b/i],
  ['Data', /\b(data engineers?|data analysts?|analytics engineers?|bi analysts?|business intelligence|etl|data warehouse|database administrators?|dba)\b/i],
  ['Support', /\b(support engineers?|technical support|customer support|solutions engineers?|implementation (engineers?|specialists?)|support specialists?|helpdesk|service desk)\b/i],
  ['Product', /\b(product managers?|product owners?|project managers?|program managers?|scrum masters?|delivery managers?|product designers?|ux|ui designers?)\b/i],
  ['Engineering', /\b(software engineers?|engineering|engineers?|developers?|programmers?|architects?|devops|sre|site reliability|full[- ]?stack|frontend|front[- ]?end|backend|back[- ]?end|mobile developers?|ios|android|qa|swe|cto|technical leads?|tech leads?)\b/i],
];

function detectCategory(jobTitle) {
  for (const [name, rx] of CATEGORY_RULES) {
    if (rx.test(jobTitle)) return name;
  }
  return 'Other';
}

function detectLevel(str) {
  if (/\bjunior\b|\bjr\b|\bintern\b|\bentry[- ]level\b/.test(str)) return 'Junior';
  if (/\bsenior\b|\bsr\b|\blead\b|\bprincipal\b|\bstaff\b/.test(str)) return 'Senior';
  if (/\bmiddle\b|\bmid[- ]level\b|\bmid\b/.test(str)) return 'Middle';
  return null;
}

const today = new Date().toISOString().slice(0, 10);
const out = [];

// Данные берём по ссылке на ноду чтения: нода Analyzed Jobs стоит с флагом
// «выполнить один раз» и пропускает дальше единственный элемент.
for (const item of $('Get row(s) in sheet').all()) {
  const id = String(item.json.job_id ?? '').trim();
  if (!id || already.has(id)) continue;

  const position = String(item.json.position ?? '').toLowerCase();
  const tags = String(item.json.tags ?? '').toLowerCase();
  const description = String(item.json.description ?? '').toLowerCase();

  const title = position + ' ' + tags;
  const text = title + ' ' + description;

  const skills = Object.keys(keywords)
    .filter(skill => keywords[skill].some(v => hasWord(text, v)));

  const level = detectLevel(title) || detectLevel(description) || 'Unknown';

  const category = detectCategory(position);

  const is_remote = hasWord(text, 'remote') || text.includes('digital nomad');

  // Дата разметки по логике расписания: вакансия попадает в сбор на следующее
  // утро после публикации, разметка идёт в 16:00 того же дня.
  const published = String(item.json.date ?? '').slice(0, 10);
  let analysisDay = today;
  if (published && published < today) {
    const next = new Date(published + 'T00:00:00Z');
    next.setUTCDate(next.getUTCDate() + 1);
    const candidate = next.toISOString().slice(0, 10);
    analysisDay = candidate <= today ? candidate : today;
  }

  out.push({ json: {
    job_id: item.json.job_id,
    date: published,
    source: item.json.source,
    company: item.json.company,
    position: item.json.position,
    is_remote,
    level,
    category,
    skills: skills.join(', '),
    analysis_date: analysisDay,
  }});
}

console.log('новых вакансий к разметке: ' + out.length + ', уже размечено: ' + already.size);
return out;
